contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
        IERC20 token = IERC20(c.mAsset());
        uint256 myTokenBalanceBefore = token.balanceOf(address(this));
        uint256 cTokenBalanceBefore = token.balanceOf(address(c));

        // This contract has no mAsset balance/allowance, so supplying must fail
        bool supplyReverted;
        try c.supplyTokenTo(amount, address(this)) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // With no credits issued, redeeming any amount must revert
        bool redeemReverted;
        try c.redeemToken(amount) returns (uint256 actualOut) {
            redeemReverted = false;
            myTokenBalanceBefore = myTokenBalanceBefore; // no-op to keep shape
        } catch {
            redeemReverted = true;
        }

        uint256 myTokenBalanceAfter = token.balanceOf(address(this));
        uint256 cTokenBalanceAfter = token.balanceOf(address(c));

        assert(
            supplyReverted &&
            redeemReverted &&
            myTokenBalanceAfter == myTokenBalanceBefore &&
            cTokenBalanceAfter == cTokenBalanceBefore
        );
    }
    receive() external payable {}
}

